var rs=UnityEngine.Object.FindObjectsByType<UnityEngine.Renderer>(UnityEngine.FindObjectsSortMode.None);var rows=new System.Collections.Generic.List<string>();foreach(var r in rs)if(r.gameObject.name=="WestPath_0"||r.gameObject.name=="WestPath_1")rows.Add(r.gameObject.name+";pos="+r.transform.position.ToString("R")+";euler="+r.transform.eulerAngles.ToString("R")+";forward="+r.transform.forward.ToString("R"));var p=UnityEngine.GameObject.FindGameObjectsWithTag("Player");foreach(var g in p)rows.Add("Player="+g.name+";pos="+g.transform.position.ToString("R"));var cam=UnityEngine.GameObject.Find("MainCamera");return "playing="+UnityEditor.EditorApplication.isPlaying+";camera="+(cam?cam.transform.position.ToString("R")+";euler="+cam.transform.eulerAngles.ToString("R"):"missing")+";"+string.Join("\n",rows);
